"""Build plan -> CMake code for the Ninja generator (step G3-1).

Every command of the plan becomes an `add_custom_command` with its output,
its inputs, its working directory (the module directory, as for Make's
`make -C`) and, for compilers, the dependency file gcc writes (`DEPFILE`,
so Ninja tracks the headers). The project uses no CMake language (`LANGUAGES
NONE`): the commands are RIOT's command lines from the data, unchanged, so
they can be compared with Make's word by word, and configuring needs no
compiler. compile_commands.json is written by the generator.

Commands with a pipe or a redirection run with `/bin/sh -c`, as Make runs
every recipe line.
"""

from __future__ import annotations

import os
import shlex


def q(text: str) -> str:
    """A quoted CMake argument with the literal value `text`."""
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"').replace("$", "\\$") \
        .replace(";", "\\;") + '"'


def args(command: str) -> str:
    """CMake arguments of a command without shell syntax (argv words)."""
    return " ".join(q(a) for a in shlex.split(command))


def shell(command: str) -> str:
    return f'/bin/sh -c {q(command)}'


def lines(plan: dict, data_files: list) -> list:
    out = [
        "# Generated by dist/tools/cmake_gen/cmake_gen.py from RIOT's data. Do not edit.",
        f"# application {plan['application']}, board {plan['board']}",
        "",
        "set_property(DIRECTORY APPEND PROPERTY CMAKE_CONFIGURE_DEPENDS",
    ]
    out += [f"  {q(p)}" for p in data_files]
    out += [")", ""]
    headers = plan["headers"]
    pre = []
    for header in headers:
        if header.get("always"):
            name = "riot_" + os.path.basename(header["output"]).replace(".", "_")
            out += [f"add_custom_target({name}",
                    f"  COMMAND {shell(header['command'])}",
                    f"  BYPRODUCTS {q(header['output'])}",
                    "  VERBATIM)"]
            continue
        depends = " ".join(q(d) for d in header.get("depends", []))
        always = [d for d in headers if d.get("always") and d["output"] in header.get("depends", [])]
        targets = " ".join("riot_" + os.path.basename(d["output"]).replace(".", "_")
                           for d in always)
        out += [f"add_custom_command(OUTPUT {q(header['output'])}",
                f"  COMMAND {shell(header['command'])}"]
        if depends or targets:
            out.append(f"  DEPENDS {depends} {targets}".rstrip())
        out += ["  VERBATIM)"]
        pre.append(header["output"])
    out.append("")
    for module in plan["modules"]:
        out.append(f"# module {module['name']} ({module['data']})")
        for obj in module["objects"]:
            depfile = os.path.splitext(obj["object"])[0] + ".d"
            out += [f"add_custom_command(OUTPUT {q(obj['object'])}",
                    f"  COMMAND {args(obj['command'])}",
                    f"  DEPENDS {q(obj['source'])} " + " ".join(q(p) for p in pre),
                    f"  DEPFILE {q(depfile)}",
                    f"  WORKING_DIRECTORY {q(obj['cwd'])}",
                    "  VERBATIM)"]
    out.append("")
    link = plan["link"]
    out += [f"add_custom_command(OUTPUT {q(link['output'])}",
            f"  BYPRODUCTS {q(link['map'])}",
            f"  COMMAND {args(link['command'])}",
            "  DEPENDS " + " ".join(q(o) for o in link["depends"]),
            "  VERBATIM)"]
    outputs = [link["output"]]
    for item in plan["files"]:
        out += [f"add_custom_command(OUTPUT {q(item['output'])}",
                f"  COMMAND {args(item['command'])}",
                f"  DEPENDS {q(link['output'])}",
                "  VERBATIM)"]
        outputs.append(item["output"])
    out += ["", "add_custom_target(riot_all ALL DEPENDS " + " ".join(q(o) for o in outputs) + ")",
            "add_custom_target(riot_print_size ALL",
            f"  COMMAND {args(plan['size'])}",
            "  VERBATIM)",
            "add_dependencies(riot_print_size riot_all)", ""]
    return out


def cmake_text(plan: dict, data_files: list) -> str:
    return "\n".join(lines(plan, data_files)) + "\n"


def project_text(name: str, python: str, generator: str, app_dir: str, variables: dict) -> str:
    """The CMakeLists.txt of the project: at configure time it runs the
    generator (data -> riot-build.cmake) and includes the result, so a change
    of the data re-runs it (CMAKE_CONFIGURE_DEPENDS)."""
    cmd = [python, generator, "plan", "-C", app_dir] + \
        [f"{k}={v}" for k, v in sorted(variables.items())]
    return "\n".join([
        "# Generated by dist/tools/cmake_gen/cmake_gen.py. Do not edit.",
        "cmake_minimum_required(VERSION 3.20)",
        f"project({name} LANGUAGES NONE)",
        "# the dependency files of gcc name absolute paths: Ninja reads them as they",
        "# are (no `cmake -E cmake_transform_depfile` step after each compile)",
        "cmake_policy(SET CMP0116 OLD)",
        "# RIOT_NO_PACKAGES=ON: do not fetch the packages (tests without network)",
        'option(RIOT_NO_PACKAGES "do not prepare the packages" OFF)',
        "set(riot_packages)",
        "if(RIOT_NO_PACKAGES)",
        "  set(riot_packages --no-packages)",
        "endif()",
        "execute_process(",
        "  COMMAND " + " ".join(q(c) for c in cmd),
        '    "BINDIR=${CMAKE_BINARY_DIR}"',
        '    --cmake "${CMAKE_BINARY_DIR}/riot-build.cmake" ${riot_packages}',
        "  RESULT_VARIABLE riot_status)",
        "if(NOT riot_status EQUAL 0)",
        '  message(FATAL_ERROR "RIOT: the build could not be generated from the data")',
        "endif()",
        'include("${CMAKE_BINARY_DIR}/riot-build.cmake")',
        "",
    ])
